package dao;
import conexion.DatabaseConnection;import modelo.Libro;import modelo.Categoria;import java.sql.*;import java.util.*;
public class LibroDAO {
 private Libro map(ResultSet r)throws SQLException{return new Libro(r.getInt("id"),r.getString("titulo"),r.getString("autor"),r.getString("isbn"),r.getString("editorial"),r.getInt("stock"),r.getInt("id_categoria"),r.getString("categoria"));}
 public List<Libro> listar()throws SQLException{List<Libro>a=new ArrayList<>();String s="SELECT l.*,c.nombre categoria FROM libros l JOIN categorias c ON c.id=l.id_categoria ORDER BY l.titulo";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s);ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}return a;}
 public void guardar(Libro l)throws SQLException{String s="INSERT INTO libros(titulo,autor,isbn,editorial,stock,id_categoria) VALUES(?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s)){set(p,l);p.executeUpdate();}}
 public void actualizar(Libro l)throws SQLException{String s="UPDATE libros SET titulo=?,autor=?,isbn=?,editorial=?,stock=?,id_categoria=? WHERE id=?";try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement(s)){set(p,l);p.setInt(7,l.getId());if(p.executeUpdate()==0)throw new SQLException("Libro no encontrado");}}
 private void set(PreparedStatement p,Libro l)throws SQLException{p.setString(1,l.getTitulo());p.setString(2,l.getAutor());p.setString(3,l.getIsbn());p.setString(4,l.getEditorial());p.setInt(5,l.getStock());p.setInt(6,l.getIdCategoria());}
 public void eliminar(int id)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM libros WHERE id=?")){p.setInt(1,id);try{p.executeUpdate();}catch(SQLIntegrityConstraintViolationException e){throw new SQLException("No se puede eliminar: el libro tiene historial de préstamos.",e);}}}
 public synchronized void prestar(int idLibro,int idEstudiante)throws SQLException{try(Connection c=DatabaseConnection.getInstance().getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock-1 WHERE id=? AND stock>0")){p.setInt(1,idLibro);if(p.executeUpdate()!=1)throw new SQLException("No hay stock disponible para ese libro.");}try(PreparedStatement p=c.prepareStatement("INSERT INTO prestamos(id_estudiante,id_libro,fecha_prestamo,fecha_devolucion,devuelto) VALUES(?,?,CURRENT_DATE,DATE_ADD(CURRENT_DATE, INTERVAL 7 DAY),FALSE)")){p.setInt(1,idEstudiante);p.setInt(2,idLibro);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}}}
}